const DP='Disease Process & Terminology', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders';

export default {
 id:'pathophysiology-3',
 event:'Pathophysiology',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Frazier’s Essentials of Human Diseases and Conditions, Zelman’s Human Diseases, and the iCEV Pathophysiology course',
 plan:[{area:DP,weight:12},{area:INTEG,weight:8},{area:MSK,weight:10},{area:CIRC,weight:12},{area:RESP,weight:8},{area:DIG,weight:12},{area:ENDO,weight:8},{area:NERV,weight:10},{area:REPRO,weight:6},{area:URIN,weight:6},{area:MENT,weight:8}],
 questions:mix([
  q(DP,'Which term describes an increase in the number of cells in a tissue?','Hyperplasia',['Hypertrophy','Metaplasia','Anaplasia'],'A','Hyperplasia adds cells, as in the endometrium; hypertrophy enlarges existing cells. Anaplasia is loss of differentiation seen in cancer.',FRA),
  q(DP,'A patient develops a rash from a medication prescribed during treatment. How is this condition described?','Iatrogenic',['Idiopathic','Congenital','Nosocomial'],'B','Iatrogenic conditions result from medical treatment. Nosocomial refers to infections acquired in a healthcare setting.',FRA),
  q(DP,'What does the term prognosis describe?','The predicted course and outcome of a disease',['The cause and origin of a disease','The signs that identify a disease','The treatment chosen for a disease'],'C','Prognosis predicts outcome; etiology is cause, and diagnosis is identifying the disease from signs, symptoms and tests.',FRA),
  q(DP,'A positive tuberculin skin test that appears 48–72 hours later is which type of hypersensitivity?','Type IV, delayed and T-cell mediated',['Type I, immediate and IgE mediated','Type II, antibody against cells','Type III, immune complex deposits'],'D','Type IV reactions take days because T cells must be recruited; contact dermatitis from poison ivy is another example.',ZEL),
  q(DP,'Which type of necrosis typically follows a heart attack?','Coagulative necrosis',['Liquefactive necrosis','Caseous necrosis','Fat necrosis'],'A','Ischemia in most solid organs causes coagulative necrosis; the brain shows liquefactive necrosis and tuberculosis caseous necrosis.',ZEL),
  q(DP,'A patient with asthma has a sudden worsening of symptoms. What is this called?','An exacerbation',['A remission','A complication','A sequela'],'B','An exacerbation is a flare of an existing disease; remission is a lessening of symptoms and a sequela is a lasting aftereffect.',FRA),
  q(INTEG,'Athlete’s foot (tinea pedis) is caused by which kind of organism?','A fungus',['A virus','A bacterium','A mite'],'C','Dermatophyte fungi thrive in warm, moist areas between the toes; antifungal medicines treat it.',FRA),
  q(INTEG,'Which process leads to acne vulgaris?','Blocked hair follicles with sebum and bacteria',['Viral infection of the sweat glands','Autoimmune attack on melanocytes','Allergic reaction to sunlight'],'D','Excess sebum and dead cells plug follicles, and Cutibacterium acnes triggers inflammation. Hormones at puberty increase sebum.',FRA),
  q(INTEG,'Which chemical released by mast cells causes the raised, itchy wheals of urticaria?','Histamine',['Insulin','Melanin','Keratin'],'A','Histamine increases capillary permeability, producing hives; antihistamines block its effects.',ZEL),
  q(INTEG,'A pressure injury shows full-thickness skin loss with visible fat but no exposed bone or muscle. What stage is it?','Stage 3',['Stage 1','Stage 2','Stage 4'],'B','Stage 2 is partial-thickness; stage 3 reaches subcutaneous fat; stage 4 exposes muscle, tendon or bone.',ZEL),
  q(MSK,'Ankylosing spondylitis is strongly associated with which genetic marker?','HLA-B27',['BRCA1','HLA-DR4 only','CFTR'],'C','This inflammatory arthritis fuses the spine and sacroiliac joints and is most common in young men with HLA-B27.',ZEL),
  q(MSK,'Osteogenesis imperfecta causes brittle bones because of a defect in which protein?','Type I collagen',['Elastin fibers','Smooth muscle actin','Keratin'],'D','Defective type I collagen weakens bone, causing frequent fractures; many patients also have blue sclerae.',ZEL),
  q(MSK,'After a crushed lower leg is placed in a cast, the patient has pain out of proportion to the injury. Which condition is suspected?','Compartment syndrome',['Osteomyelitis','Plantar fasciitis','Stress fracture'],'A','Swelling within a closed muscle compartment raises pressure and cuts off blood flow; it is a surgical emergency.',FRA),
  q(MSK,'A child with bowed legs has a diet low in vitamin D and little sun exposure. What is the likely diagnosis?','Rickets',['Scurvy','Osteoporosis','Gout'],'B','Vitamin D deficiency prevents normal mineralization of growing bone; in adults the same deficiency causes osteomalacia.',FRA),
  q(MSK,'Which condition is inflammation of the fluid-filled sacs that cushion joints?','Bursitis',['Tendinitis','Synovitis of muscle','Myositis'],'C','Bursae reduce friction near joints; repetitive motion or pressure can inflame them, as in the shoulder or elbow.',FRA),
  q(CIRC,'Why do varicose veins develop?','Faulty valves let blood pool',['Arteries harden with plaque','Lymph vessels become blocked','Platelets clump inside veins'],'D','When one-way valves fail, blood pools in superficial leg veins, which become twisted and enlarged.',FRA),
  q(CIRC,'In Raynaud phenomenon, fingers turn white, then blue, then red. What causes this?','Spasm of small arteries',['Clots in the deep veins','Damage to the heart valves','Leakage of the lymph vessels'],'A','Cold or stress triggers vasospasm of digital arteries; color returns as blood flow is restored.',ZEL),
  q(CIRC,'Which is the most common type of cancer in children?','Acute lymphoblastic leukemia',['Chronic lymphocytic leukemia','Chronic myeloid leukemia','Multiple myeloma'],'B','ALL is the most common childhood cancer and often responds well to treatment; chronic leukemias are mostly adult diseases.',ZEL),
  q(CIRC,'Infectious mononucleosis, with fever, sore throat and swollen lymph nodes, is caused mainly by which virus?','Epstein-Barr virus',['Varicella-zoster virus','Human papillomavirus','Hepatitis B virus'],'C','EBV spreads through saliva. Patients may have an enlarged spleen and should avoid contact sports to prevent rupture.',FRA),
  q(CIRC,'An abdominal aortic aneurysm is especially dangerous because it can:','Rupture and cause massive bleeding',['Turn into a malignant tumor','Block the flow of lymph','Infect the heart valves'],'D','A ruptured AAA causes severe pain and shock and is often fatal; smoking and hypertension are major risk factors.',FRA),
  q(CIRC,'Infective endocarditis is characterized by which finding on the heart valves?','Vegetations of bacteria and clot',['Calcium deposits from aging','Fatty plaques from cholesterol','Scar tissue from a heart attack'],'A','Bacteria colonize damaged valves, forming vegetations that can break off as emboli; IV drug use is a risk factor.',ZEL),
  q(RESP,'A tall, thin young man has sudden chest pain and shortness of breath at rest. Which condition is most likely?','Spontaneous pneumothorax',['A pulmonary embolism','Cystic fibrosis flare','Bronchiectasis'],'B','Small blebs on the lung surface can rupture without injury, letting air into the pleural space and collapsing the lung.',FRA),
  q(RESP,'Pertussis (whooping cough) is caused by which organism?','Bordetella pertussis',['Haemophilus influenzae','Mycobacterium tuberculosis','Streptococcus pyogenes'],'C','Pertussis causes violent coughing fits followed by a “whoop”; it is most dangerous in infants and prevented by vaccination.',FRA),
  q(RESP,'A toddler has a barking cough and stridor after a cold. What is the most likely condition?','Croup',['Epiglottitis','Asthma','Pertussis'],'D','Croup is usually viral (often parainfluenza) and swells the area below the vocal cords, producing a seal-like bark.',FRA),
  q(RESP,'What happens during obstructive sleep apnea?','The upper airway collapses during sleep',['The brain stops sending breathing signals','The alveoli fill with fluid at night','The diaphragm becomes paralyzed'],'A','Relaxed throat tissues block airflow, causing pauses, snoring and daytime sleepiness; obesity is a major risk factor.',ZEL),
  q(DIG,'A patient has right upper quadrant pain after a fatty meal and pain when pressed under the right ribs during a deep breath. What is likely?','Cholecystitis',['Appendicitis','Pancreatitis','Diverticulitis'],'B','Gallbladder inflammation, usually from gallstones, produces a positive Murphy sign and pain after fatty foods.',FRA),
  q(DIG,'Which statement best describes irritable bowel syndrome?','Bowel symptoms without visible damage',['Ulcers through the colon lining','Autoimmune damage to the villi','Pouches that bulge from the colon'],'C','IBS causes pain with diarrhea and/or constipation but no structural or inflammatory damage on testing.',ZEL),
  q(DIG,'How is hepatitis B mainly transmitted?','Through blood and sexual contact',['Through contaminated food and water','Through airborne droplets','Through mosquito bites'],'D','Hepatitis B spreads by blood, sexual contact and from mother to baby; a vaccine is available.',FRA),
  q(DIG,'What is a hiatal hernia?','Part of the stomach pushed above the diaphragm',['A tear in the lining of the esophagus','A bulge of intestine at the navel','A narrowing of the pyloric sphincter'],'A','The stomach protrudes through the diaphragm’s esophageal opening, which often worsens acid reflux.',FRA),
  q(DIG,'Bloating and diarrhea after drinking milk are most often due to a deficiency of which enzyme?','Lactase',['Amylase','Lipase','Pepsin'],'B','Undigested lactose draws water into the bowel and is fermented by bacteria, producing gas and diarrhea.',FRA),
  q(DIG,'From which lesions do most colorectal cancers develop?','Adenomatous polyps',['Hemorrhoids','Anal fissures','Hyperplastic villi'],'C','Most colorectal cancers begin as adenomas that become malignant over years, which is why screening removes polyps.',ZEL),
  q(ENDO,'SIADH causes the body to retain water. Which blood finding results?','Low sodium',['High sodium','Low potassium','High glucose'],'D','Excess ADH makes the kidneys hold water, diluting the blood and causing hyponatremia, which can lead to confusion and seizures.',ZEL),
  q(ENDO,'A pheochromocytoma causes episodes of severe hypertension, sweating and headache. Where is this tumor found?','Adrenal medulla',['Adrenal cortex','Anterior pituitary','Parathyroid gland'],'A','The tumor releases bursts of epinephrine and norepinephrine, which raise blood pressure and heart rate.',ZEL),
  q(ENDO,'Primary hyperparathyroidism causes kidney stones and bone pain because of high blood levels of:','Calcium',['Potassium','Sodium','Iodine'],'B','Excess parathyroid hormone pulls calcium from bone and raises blood calcium—“stones, bones, groans and moans.”',ZEL),
  q(ENDO,'Gestational diabetes is first recognized during which time?','Pregnancy',['Infancy','Puberty','Menopause'],'C','Placental hormones increase insulin resistance; the condition usually resolves after delivery but raises later type 2 risk.',FRA),
  q(NERV,'How is Huntington disease inherited?','Autosomal dominant',['Autosomal recessive','X-linked recessive','Mitochondrial'],'D','One copy of the expanded CAG repeat causes disease, so each child of an affected parent has a 50% chance.',ZEL),
  q(NERV,'Amyotrophic lateral sclerosis (ALS) destroys which cells?','Upper and lower motor neurons',['Sensory neurons in the skin','Myelin in the brain only','Dopamine cells in the midbrain'],'A','Loss of motor neurons causes progressive weakness and paralysis, while sensation and thinking are usually spared.',ZEL),
  q(NERV,'Which statement best describes cerebral palsy?','A nonprogressive brain injury affecting movement',['A progressive loss of motor neurons','An infection of the spinal cord in infancy','A genetic muscle-wasting disease'],'B','Damage to the developing brain before, during or soon after birth causes lifelong but nonworsening movement problems.',FRA),
  q(NERV,'Age-related macular degeneration mainly causes loss of which part of vision?','Central vision',['Peripheral vision','Night vision only','Color vision only'],'C','The macula provides sharp central vision for reading and faces; glaucoma, in contrast, first affects peripheral vision.',FRA),
  q(NERV,'Which triad of symptoms describes Ménière disease?','Vertigo, tinnitus and hearing loss',['Fever, stiff neck and rash','Tremor, rigidity and slow movement','Headache, aura and nausea'],'D','Excess fluid in the inner ear causes episodes of spinning, ringing and fluctuating hearing loss.',FRA),
  q(REPRO,'Which virus causes most cases of cervical cancer?','Human papillomavirus',['Herpes simplex virus','Epstein-Barr virus','Hepatitis C virus'],'A','High-risk HPV types cause cervical cell changes; HPV vaccination and Pap or HPV screening prevent most cases.',FRA),
  q(REPRO,'Why is untreated chlamydia a common cause of infertility in women?','It can cause pelvic inflammatory disease',['It always causes ovarian cancer','It destroys estrogen production','It blocks the cervix with cysts'],'B','Chlamydia is often silent but can ascend to the tubes, causing scarring that leads to infertility and ectopic pregnancy.',FRA),
  q(REPRO,'A teen boy has sudden, severe scrotal pain and swelling. Why is testicular torsion an emergency?','The twisted cord cuts off blood flow',['The testis may become cancerous','An infection spreads to the kidneys','Fluid will fill the abdomen'],'C','Twisting of the spermatic cord blocks blood supply; surgery within hours is needed to save the testis.',FRA),
  q(URIN,'What are the two most common causes of chronic kidney disease?','Diabetes and hypertension',['Kidney stones and UTIs','Trauma and dehydration','Smoking and alcohol use'],'D','Both damage the small vessels of the glomeruli over years, gradually reducing kidney function.',FRA),
  q(URIN,'Wilms tumor is a kidney cancer that occurs mainly in which group?','Young children',['Older adults','Pregnant women','Teenage athletes'],'A','Wilms tumor (nephroblastoma) often appears as a painless abdominal mass in children under 5.',FRA),
  q(URIN,'Which findings suggest pyelonephritis rather than a simple bladder infection?','Fever, chills and flank pain',['Burning urination only','Cloudy urine only','Frequent urination only'],'B','Infection that reaches the kidney causes systemic signs and costovertebral angle tenderness.',FRA),
  q(MENT,'Which feature helps distinguish delirium from dementia?','Delirium starts suddenly and fluctuates',['Delirium develops slowly over years','Delirium never affects attention','Delirium cannot be reversed'],'C','Delirium has an acute onset, fluctuating attention and a treatable cause; dementia is gradual and progressive.',ZEL),
  q(MENT,'Which description fits panic disorder?','Recurrent sudden attacks of intense fear',['Constant worry about many daily events','Fear of a specific object or situation','Repetitive thoughts with rituals'],'D','Panic attacks bring a racing heart, chest tightness and fear of dying, plus ongoing worry about future attacks.',ZEL),
  q(MENT,'Autism spectrum disorder is defined by differences in which two areas?','Social communication and repetitive behaviors',['Reading ability and math ability only','Mood and sleep patterns at night','Memory and motor coordination'],'A','Signs appear in early childhood and vary widely in severity, which is why it is called a spectrum.',ZEL),
  q(MENT,'Depression that returns each fall and winter and lifts in spring is described as having which pattern?','A seasonal pattern',['A psychotic pattern','A manic pattern','A postpartum pattern'],'B','Seasonal affective disorder is linked to reduced daylight; light therapy is a common treatment.',ZEL)
 ],5303)
};
